#include <iostream>
#include <string>
using namespace std;

class Cat {
private:
    string name;
    int fish;

public:
    Cat(string n, int f) : name(n), fish(f) {}

    void setName(string n) {
        name = n;
    }

    void eat() {
        fish = fish + 1;
        cout << name << " 吃掉了一条，现在有 " << fish << " 条" << endl;
    }
};

int main() {
    Cat c1("小橘", 2);
    c1.eat();
    c1.eat();
    c1.setName("大胖");
    c1.eat();
    return 0;
}
